// ============================================================
// PARSE MULTIPLE ANSIBLE HOSTS FROM ONE STDOUT
// ============================================================

const output = $json.stdout || '';

const lines = output.split(/\r?\n/);

const results = [];

let currentHostname = '';
let auditStarted = false;

// ------------------------------------------------------------
// Process each line
// ------------------------------------------------------------

for (let i = 0; i < lines.length; i++) {

    const rawLine = lines[i];
    const line = rawLine.trim();

    if (!line) {
        continue;
    }

    // --------------------------------------------------------
    // Detect a NEW HOST section
    // --------------------------------------------------------

    if (line === '===== HOST =====') {

        auditStarted = false;
        currentHostname = '';

        // Next non-empty line contains the Ansible host
        for (let j = i + 1; j < lines.length; j++) {

            const nextLine = lines[j].trim();

            if (!nextLine) {
                continue;
            }

            /*
             * Example:
             *
             * infinity.nitlkanchi.com | SUCCESS | rc=0 >>
             */

            currentHostname = nextLine
                .split('|')[0]
                .trim();

            break;
        }

        continue;
    }

    // --------------------------------------------------------
    // Detect directory audit section
    // --------------------------------------------------------

    if (line.includes('DIRECTORY PERMISSIONS')) {

        auditStarted = true;
        continue;
    }

    // --------------------------------------------------------
    // Ignore lines until a valid host and audit section exist
    // --------------------------------------------------------

    if (!currentHostname || !auditStarted) {
        continue;
    }

    // --------------------------------------------------------
    // Expected:
    //
    // 775 root root /data
    // 775 app app /data/data1
    // 755 mysql mysql /data/mysql
    // --------------------------------------------------------

    const match = line.match(
        /^([0-7]{3,4})\s+(\S+)\s+(\S+)\s+(.+)$/
    );

    if (!match) {
        continue;
    }

    const permission = match[1];
    const owner = match[2];
    const group = match[3];
    const path = match[4];

    // --------------------------------------------------------
    // Calculate directory depth
    // --------------------------------------------------------

    const depth =
        path === '/'
            ? 0
            : path.split('/').filter(Boolean).length;

    // --------------------------------------------------------
    // Add result
    // --------------------------------------------------------

    results.push({
        json: {
            hostname: currentHostname,
            path: path,
            permission: permission,
            owner: owner,
            group: group,
            depth: depth,
            expected_permission: '770',
            permission_status:
                permission === '770'
                    ? 'PASS'
                    : 'FAIL'
        }
    });
}

// ============================================================
// RETURN ALL HOST RESULTS
// ============================================================

return results;

