=// ============================================================
// LINUX DIRECTORY PERMISSION AUDIT REPORT
// ============================================================

// Read all items from Audit Configuration
const items = $input.all();

// ------------------------------------------------------------
// Helper: clean hostname
// ------------------------------------------------------------
function cleanHostname(hostname) {
    if (!hostname) {
        return 'Unknown';
    }

    // Handles values such as:
    // hostname | SUCCESS | rc=0 >>
    return hostname
        .split('|')[0]
        .replace(/[\r\n]/g, '')
        .trim();
}

// ------------------------------------------------------------
// Helper: escape HTML
// ------------------------------------------------------------
function escapeHtml(value) {
    if (value === null || value === undefined) {
        return '';
    }

    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

// ------------------------------------------------------------
// Convert input data
// ------------------------------------------------------------
const records = items.map(item => {
    const data = item.json || {};

    const permission = String(data.permission || '');
    const expectedPermission = String(
        data.expected_permission || '770'
    );

    return {
        hostname: cleanHostname(data.hostname),
        path: data.path || '',
        permission: permission,
        owner: data.owner || '',
        group: data.group || '',
        depth: Number(data.depth || 0),
        expected_permission: expectedPermission,
        permission_status:
            permission === expectedPermission ? 'PASS' : 'FAIL'
    };
});

// ------------------------------------------------------------
// Remove invalid records
// ------------------------------------------------------------
const validRecords = records.filter(record => {
    return record.path && record.permission;
});

// ------------------------------------------------------------
// Group records by hostname
// ------------------------------------------------------------
const hostGroups = {};

for (const record of validRecords) {

    if (!hostGroups[record.hostname]) {
        hostGroups[record.hostname] = [];
    }

    hostGroups[record.hostname].push(record);
}

// ------------------------------------------------------------
// Overall statistics
// ------------------------------------------------------------
const totalDirectories = validRecords.length;

const failedDirectories = validRecords.filter(
    r => r.permission_status === 'FAIL'
);

const passedDirectories = validRecords.filter(
    r => r.permission_status === 'PASS'
);

const totalHosts = Object.keys(hostGroups).length;

const overallStatus =
    failedDirectories.length > 0
        ? 'CRITICAL'
        : 'PASS';

// ------------------------------------------------------------
// Build host summary
// ------------------------------------------------------------
let hostSummaryRows = '';

for (const [hostname, recordsForHost] of Object.entries(hostGroups)) {

    const hostTotal = recordsForHost.length;

    const hostFailed = recordsForHost.filter(
        r => r.permission_status === 'FAIL'
    ).length;

    const hostPassed = recordsForHost.filter(
        r => r.permission_status === 'PASS'
    ).length;

    const hostStatus =
        hostFailed > 0
            ? 'FAIL'
            : 'PASS';

    hostSummaryRows += `
        <tr>
            <td>${escapeHtml(hostname)}</td>
            <td>${hostTotal}</td>
            <td>${hostPassed}</td>
            <td>${hostFailed}</td>
            <td>
                <span class="${hostStatus === 'FAIL'
                    ? 'status-fail'
                    : 'status-pass'}">
                    ${hostStatus}
                </span>
            </td>
        </tr>
    `;
}

// ------------------------------------------------------------
// Build detailed failure report
// ------------------------------------------------------------

let failureRows = '';

for (const record of failedDirectories) {

    failureRows += `
        <tr>
            <td>${escapeHtml(record.hostname)}</td>
            <td>${escapeHtml(record.path)}</td>
            <td>${escapeHtml(record.permission)}</td>
            <td>${escapeHtml(record.expected_permission)}</td>
            <td>${escapeHtml(record.owner)}</td>
            <td>${escapeHtml(record.group)}</td>
            <td>${record.depth}</td>
            <td>
                <span class="status-fail">
                    FAIL
                </span>
            </td>
        </tr>
    `;
}

// ------------------------------------------------------------
// If no failures
// ------------------------------------------------------------
if (failedDirectories.length === 0) {

    failureRows = `
        <tr>
            <td colspan="8" class="all-good">
                No directory permission violations found.
                All audited directories are set to 770.
            </td>
        </tr>
    `;
}

// ------------------------------------------------------------
// Build HTML report
// ------------------------------------------------------------
const html = `
<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<style>

body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 14px;
    color: #333333;
    margin: 20px;
}

h2 {
    color: #1f4e79;
}

h3 {
    color: #1f4e79;
    margin-top: 30px;
}

.summary {
    border-collapse: collapse;
    width: 100%;
    margin-bottom: 25px;
}

.summary td {
    border: 1px solid #dddddd;
    padding: 10px;
}

.summary .label {
    font-weight: bold;
    width: 220px;
}

.status-box {
    padding: 10px;
    margin-bottom: 20px;
    font-weight: bold;
}

.critical {
    background-color: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.pass {
    background-color: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

table {
    border-collapse: collapse;
    width: 100%;
    margin-top: 10px;
}

th {
    background-color: #1f4e79;
    color: white;
    padding: 8px;
    border: 1px solid #cccccc;
    text-align: left;
}

td {
    padding: 7px;
    border: 1px solid #dddddd;
}

tr:nth-child(even) {
    background-color: #f8f9fa;
}

.status-fail {
    color: #b02a37;
    font-weight: bold;
}

.status-pass {
    color: #146c43;
    font-weight: bold;
}

.all-good {
    text-align: center;
    padding: 15px;
    color: #146c43;
    font-weight: bold;
}

.footer {
    margin-top: 30px;
    color: #666666;
    font-size: 12px;
}

</style>

</head>

<body>

<h2>Linux Server Directory Permission Audit</h2>

<div class="status-box ${overallStatus === 'CRITICAL'
    ? 'critical'
    : 'pass'}">

    Overall Status:
    ${overallStatus}

</div>

<table class="summary">

<tr>
    <td class="label">Audit Date</td>
    <td>${new Date().toLocaleString('en-IN')}</td>
</tr>

<tr>
    <td class="label">Servers Audited</td>
    <td>${totalHosts}</td>
</tr>

<tr>
    <td class="label">Directories Audited</td>
    <td>${totalDirectories}</td>
</tr>

<tr>
    <td class="label">Permission Requirement</td>
    <td>770</td>
</tr>

<tr>
    <td class="label">Directories PASS</td>
    <td>${passedDirectories.length}</td>
</tr>

<tr>
    <td class="label">Directories FAIL</td>
    <td>${failedDirectories.length}</td>
</tr>

</table>


<h3>Server Summary</h3>

<table>

<thead>

<tr>
    <th>Hostname</th>
    <th>Total Directories</th>
    <th>PASS</th>
    <th>FAIL</th>
    <th>Status</th>
</tr>

</thead>

<tbody>

${hostSummaryRows}

</tbody>

</table>


<h3>Directory Permission Violations</h3>

<table>

<thead>

<tr>
    <th>Hostname</th>
    <th>Directory</th>
    <th>Current Permission</th>
    <th>Expected</th>
    <th>Owner</th>
    <th>Group</th>
    <th>Depth</th>
    <th>Status</th>
</tr>

</thead>

<tbody>

${failureRows}

</tbody>

</table>


<div class="footer">

<p>
<strong>Audit Scope:</strong>
Main directory and maximum 4 subdirectory levels.
</p>

<p>
<strong>Permission Requirement:</strong>
Directory permission must be 770.
</p>

<p>
This report was automatically generated by the n8n Linux Server Audit workflow.
</p>

</div>

</body>

</html>
`;

// ------------------------------------------------------------
// Email subject
// ------------------------------------------------------------
const subject =
    overallStatus === 'CRITICAL'
        ? `CRITICAL - Linux Directory Permission Audit - ${failedDirectories.length} violation(s)`
        : `PASS - Linux Directory Permission Audit`;

// ------------------------------------------------------------
// Return email-ready JSON
// ------------------------------------------------------------
return [
    {
        json: {
            status: overallStatus,

            overall_status: overallStatus,

            total_hosts: totalHosts,

            total_directories: totalDirectories,

            passed_directories: passedDirectories.length,

            failed_directories: failedDirectories.length,

            expected_permission: '770',

            subject: subject,

            message: {
                subject: subject,

                body: {
                    contentType: 'HTML',

                    content: html
                },

                toRecipients: [
                    {
                        emailAddress: {
                            address: 'prem.d@ninestars.in'
                        }
                    }
                ]
            }
        }
    }
];
